#include <fvf.hpp>
#include <cmath>
#include <complex>
#include <heldefs_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <Need.hpp>
#include <W1jet.hpp>

std::complex<double> Fvf(int st, int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  using namespace mxpart_mod;
  using namespace sprods_com_mod;
  using namespace heldefs_mod;

  std::complex<double> Fvf_result;
  std::complex<double> I3m123456, I3m563412;

  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  I3m123456 = i3m(s(j1, j2), s(j3, j4), s(j5, j6));
  I3m563412 = I3m123456;

  if (st == hqpqbmgpgm) {
    Fvf_result =
        -std::pow(zab2(j5, j2, j4, j1), 2) / (za(j5, j6) * zb(j1, j2) * std::pow(zab2(j3, j1, j2, j4), 2))
        * Lsm1_2mh(s(j3, j4), t(j1, j2, j4), s(j1, j2), s(j5, j6))
        - std::pow(zab2(j2, j1, j3, j6), 2) / (za(j1, j2) * zb(j5, j6) * std::pow(zab2(j3, j1, j2, j4), 2))
        * Lsm1_2mh(s(j3, j4), t(j1, j2, j3), s(j1, j2), s(j5, j6))

        - I3m123456 * za(j4, j5) * zb(j1, j3)
        * zab2(j2, j1, j3, j6) / (2.0 * zab2(j3, j1, j2, j4) * t(j1, j2, j3))

        - I3m123456 * za(j2, j4) * zb(j3, j6)
        * zab2(j5, j2, j4, j1) / (2.0 * zab2(j3, j1, j2, j4) * t(j1, j2, j4))

        + I3m563412 * za(j2, j4) * zb(j3, j6)
        * zab2(j5, j3, j6, j1) / (2.0 * zab2(j3, j1, j2, j4) * t(j3, j5, j6))

        + I3m563412 * za(j4, j5) * zb(j1, j3)
        * zab2(j2, j4, j5, j6) / (2.0 * zab2(j3, j1, j2, j4) * t(j4, j5, j6));
  } else if (st == hqpqbmgpgp) {
    Fvf_result = -std::pow(za(j2, j5), 2) / (za(j1, j2) * za(j5, j6) * std::pow(za(j3, j4), 2))
        * Lsm1_2me(t(j1, j2, j3), t(j1, j2, j4), s(j1, j2), s(j5, j6));
  }

  Fvf_result = Fvf_result;  // @coverage-probe
  return Fvf_result;
}

extern "C" {
  std::complex<double> Fvf_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {
    using namespace mxpart_mod;

    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);

    return Fvf(st, j1, j2, j3, j4, j5, j6, za, zb);
  }
}
